        ret = utf8proc_iterate(ptr, -1, &c);

        if(ret < 0 || ret == 0) break;

        bytes += ret;
        ptr += ret;

        utf8proc_tolower(c);
        utf8proc_toupper(c);
        utf8proc_totitle(c);
        utf8proc_islower(c);
        utf8proc_isupper(c);
        utf8proc_charwidth(c);
        utf8proc_category(c);
        utf8proc_category_string(c);
        utf8proc_codepoint_valid(c);

        utf8proc_grapheme_break(c_prev, c);
        utf8proc_grapheme_break_stateful(c_prev, c, &state);

        c_prev = c;
    }

    utf8proc_int32_t *copy = size >= 4 ? malloc(size) : NULL;

    if(copy)
